const items = $input.all();

/**
 * IMPORTANTE:
 * Substitua pelo domínio que será usado para criar os usuários.
 *
 * Os e-mails do input estão incompletos:
 * alice.silva@
 *
 * O resultado será:
 * alice.silva@seudominio.com.br
 */
const EMAIL_DOMAIN = $('preencha o dominio do email a ser usado.').first().json.email_domain

/**
 * Localiza a estrutura que contém fake_10_usuarios.
 * Funciona com:
 *
 * {
 *   "Estrutura_de_teste": {
 *     "fake_10_usuarios": [...]
 *   }
 * }
 */
function obterEstrutura(json) {
  if (!json || typeof json !== 'object' || Array.isArray(json)) {
    throw new Error('O input recebido não possui um objeto JSON válido.');
  }

  if (Array.isArray(json.fake_10_usuarios)) {
    return json;
  }

  for (const valor of Object.values(json)) {
    if (
      valor &&
      typeof valor === 'object' &&
      !Array.isArray(valor) &&
      Array.isArray(valor.fake_10_usuarios)
    ) {
      return valor;
    }
  }

  throw new Error(
    'A propriedade "fake_10_usuarios" não foi encontrada no input.'
  );
}

/**
 * Remove acentos e caracteres que podem gerar erro no nome.
 * Exemplo:
 * João Pereira -> Joao Pereira
 */
function normalizarNome(valor) {
  return String(valor || '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9 .@_-]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Completa e valida o e-mail.
 */
function montarEmail(valor, indice) {
  let email = String(valor || '')
    .trim()
    .toLowerCase();

  if (!email) {
    throw new Error(`O usuário ${indice + 1} não possui e-mail.`);
  }

  if (email.endsWith('@')) {
    email += EMAIL_DOMAIN;
  }

  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailValido.test(email)) {
    throw new Error(
      `O e-mail "${email}" do usuário ${indice + 1} é inválido.`
    );
  }

  return email;
}

/**
 * Valida a senha segundo os requisitos mínimos:
 * - pelo menos 6 caracteres;
 * - ao menos uma letra minúscula;
 * - ao menos uma letra maiúscula;
 * - ao menos um número.
 */
function validarSenha(valor, nome) {
  const senha = String(valor || '');

  const senhaValida =
    senha.length >= 6 &&
    /[a-z]/.test(senha) &&
    /[A-Z]/.test(senha) &&
    /\d/.test(senha);

  if (!senhaValida) {
    throw new Error(
      `A senha do usuário "${nome}" não atende aos requisitos mínimos.`
    );
  }

  return senha;
}

/**
 * Normaliza o papel somente para criar um identificador interno.
 * O papel não é enviado como função da Kommo.
 */
function normalizarPapel(valor) {
  return String(valor || 'usuario')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9_-]/g, '_');
}

/**
 * Permissões padrão dos usuários.
 *
 * A = acesso permitido para todos os registros.
 *
 * Posteriormente, você pode substituir estas permissões
 * por role_id quando já tiver criado as funções SDR e Closer.
 */
function montarPermissoes() {
  return {
    leads: {
      view: 'A',
      edit: 'A',
      add: 'A',
      delete: 'A',
      export: 'A'
    },
    contacts: {
      view: 'A',
      edit: 'A',
      add: 'A',
      delete: 'A',
      export: 'A'
    },
    companies: {
      view: 'A',
      edit: 'A',
      add: 'A',
      delete: 'A',
      export: 'A'
    },
    tasks: {
      edit: 'A',
      delete: 'A'
    },
    mail_access: false,
    catalog_access: false,
    status_rights: null,
    is_admin: false,
    is_free: false,
    group_id: null
  };
}

const usuarios = [];

for (const item of items) {
  const estrutura = obterEstrutura(item.json);
  const usuariosRecebidos = estrutura.fake_10_usuarios;

  for (const [indice, usuario] of usuariosRecebidos.entries()) {
    const name = normalizarNome(usuario.nome);

    if (!name) {
      throw new Error(`O usuário ${indice + 1} não possui nome válido.`);
    }

    const papel = normalizarPapel(usuario.papel);

    usuarios.push({
      name,
      email: montarEmail(usuario.email, indice),
      password: validarSenha(usuario.senha, name),
      lang: 'en',
      rights: montarPermissoes(),
      request_id: `${papel}_${indice + 1}`
    });
  }
}

if (usuarios.length === 0) {
  throw new Error('Nenhum usuário foi encontrado para criação.');
}

/**
 * A API aceita no máximo 10 usuários por requisição.
 * O código cria um item para cada lote.
 */
const TAMANHO_DO_LOTE = 10;
const resultado = [];

for (let inicio = 0; inicio < usuarios.length; inicio += TAMANHO_DO_LOTE) {
  const body = usuarios.slice(inicio, inicio + TAMANHO_DO_LOTE);

  resultado.push({
    json: {
      lote: Math.floor(inicio / TAMANHO_DO_LOTE) + 1,
      quantidade_usuarios: body.length,
      body
    }
  });
}

return resultado;

const items = $input.all();

/**
 * Converte os nomes utilizados na estrutura de entrada
 * para os tipos aceitos pela API da Kommo.
 */
function normalizarTipo(tipo) {
  const mapaTipos = {
    text: 'text',
    textarea: 'textarea',
    number: 'numeric',
    numeric: 'numeric',
    checkbox: 'checkbox',
    select: 'select',
    multiselect: 'multiselect',
    radio: 'radiobutton',
    radiobutton: 'radiobutton',
    date: 'date',
    datetime: 'date_time',
    date_time: 'date_time',
    url: 'url',
    birthday: 'birthday',
    price: 'price'
  };

  const tipoNormalizado = String(tipo || '')
    .trim()
    .toLowerCase();

  const tipoKommo = mapaTipos[tipoNormalizado];

  if (!tipoKommo) {
    throw new Error(`Tipo de campo não suportado: "${tipo}".`);
  }

  return tipoKommo;
}

/**
 * Converte cada campo personalizado para o formato esperado pela Kommo.
 */
function montarCampo(campo, indice, entidade) {
  const name = String(campo?.name || '').trim();

  if (!name) {
    throw new Error(
      `O campo ${indice + 1} da entidade "${entidade}" não possui name.`
    );
  }

  const type = normalizarTipo(campo?.type);

  const campoFormatado = {
    name,
    type,
    sort: indice + 1
  };

  /**
   * Campos de seleção precisam possuir enums.
   * O código aceita options ou enums na entrada.
   */
  if (['select', 'multiselect', 'radiobutton'].includes(type)) {
    const opcoes = campo.options || campo.enums || [];

    if (!Array.isArray(opcoes) || opcoes.length === 0) {
      throw new Error(
        `O campo "${name}" da entidade "${entidade}" precisa possuir opções.`
      );
    }

    campoFormatado.enums = opcoes.map((opcao, opcaoIndex) => {
      /**
       * Aceita tanto:
       * "Desenvolvimento Web"
       *
       * quanto:
       * { "value": "Desenvolvimento Web" }
       */
      const value =
        typeof opcao === 'object'
          ? String(opcao.value || '').trim()
          : String(opcao || '').trim();

      if (!value) {
        throw new Error(
          `A opção ${opcaoIndex + 1} do campo "${name}" está vazia.`
        );
      }

      return {
        value,
        sort: opcaoIndex + 1
      };
    });
  }

  return campoFormatado;
}

/**
 * Localiza a estrutura principal independentemente
 * do nome utilizado na primeira propriedade.
 *
 * Exemplo recebido:
 * {
 *   "Estrutura_de_teste": {
 *      ...
 *   }
 * }
 */
function obterEstrutura(json) {
  if (!json || typeof json !== 'object') {
    throw new Error('O item recebido não possui um JSON válido.');
  }

  const chaves = Object.keys(json);

  if (chaves.length === 1) {
    const possivelEstrutura = json[chaves[0]];

    if (
      possivelEstrutura &&
      typeof possivelEstrutura === 'object' &&
      !Array.isArray(possivelEstrutura)
    ) {
      return possivelEstrutura;
    }
  }

  return json;
}

/**
 * Relação entre as propriedades da entrada
 * e as entidades aceitas pela API da Kommo.
 */
const configuracoes = [
  {
    propriedade: 'campos_personalizados_lead',
    entity_type: 'leads'
  },
  {
    propriedade: 'campos_personalizados_contato',
    entity_type: 'contacts'
  },
  {
    propriedade: 'campos_personalizados_empresa',
    entity_type: 'companies'
  }
];

const resultado = [];

for (const item of items) {
  const estrutura = obterEstrutura(item.json);

  for (const config of configuracoes) {
    const campos = estrutura[config.propriedade];

    /**
     * Ignora entidades que não possuam campos personalizados.
     */
    if (!Array.isArray(campos) || campos.length === 0) {
      continue;
    }

    const body = campos.map((campo, indice) =>
      montarCampo(campo, indice, config.entity_type)
    );

    resultado.push({
      json: {
        entity_type: config.entity_type,
        body
      }
    });
  }
}

if (resultado.length === 0) {
  throw new Error('Nenhum campo personalizado foi encontrado na entrada.');
}

return resultado;

const items = $input.all();

return items.map((item, funilIndex) => {
  const funil = item.json;

  const nomeFunil = String(funil.nome || '').trim();
  const etapas = Array.isArray(funil.etapas) ? funil.etapas : [];

  if (!nomeFunil) {
    throw new Error(`O funil do item ${funilIndex + 1} não possui nome.`);
  }

  if (etapas.length === 0) {
    throw new Error(`O funil "${nomeFunil}" não possui etapas.`);
  }

  const statuses = etapas.map((etapa, etapaIndex) => {
    const nomeEtapa = String(etapa.nome || '').trim();
    const descricaoEtapa = String(etapa.descricao || '').trim();

    if (!nomeEtapa) {
      throw new Error(
        `A etapa ${etapaIndex + 1} do funil "${nomeFunil}" não possui nome.`
      );
    }

    return {
      name: nomeEtapa,
      sort: etapaIndex + 1,
      descriptions: {
        level: "newbie",
        description: descricaoEtapa
      }
    };
  });

  return {
    json: {
      name: nomeFunil,
      sort: funilIndex + 1,

      // Apenas o primeiro funil será definido como principal.
      // Caso nenhum deva ser principal, altere para false.
      is_main: funilIndex === 0,

      is_unsorted_on: false,
      _embedded: {
        statuses
      }
    }
  };
});
